using System.Security.Principal;
using System.Text.Json;
using ContentOS.Application;
using ContentOS.Contracts;
using ContentOS.Domain;
using ContentOS.Foundation.Tests;
using ContentOS.Infrastructure;
using ContentOS.Integrations;
using Microsoft.Extensions.DependencyInjection;

if (!OperatingSystem.IsWindows()) throw new PlatformNotSupportedException("This demo verifies the Windows account boundary.");
var directory = args[0]; var actor = WindowsIdentity.GetCurrent().Name;
using var root = CustomerTestFixture.Services(); using var scope = root.CreateScope(); var s = scope.ServiceProvider; var f = await CustomerTestFixture.Setup(s, actor); var db = s.GetRequiredService<CoreDbContext>(); db.Members.Add(new() { TenantId = f.Tenant, Actor = actor, Permission = "Administrator" }); await db.SaveChangesAsync(); var admin = new CoreScope(f.Tenant, actor); var w = s.GetRequiredService<ICustomerWorkbench>();
await w.GrantAsync(admin, new(Guid.NewGuid(), f.User, 100, DateTimeOffset.UtcNow.AddDays(30), "fixture:demo-grant"), default);
async Task<Guid?> Reserve(string key) { using var own = root.CreateScope(); try { return await own.ServiceProvider.GetRequiredService<ICustomerWorkbench>().ReserveAsync(f.Alice, new(Guid.NewGuid(), f.Profile, key, 80), default); } catch (RuntimeValidationException) { return null; } }
var races = await Task.WhenAll(Reserve("demo-race-a"), Reserve("demo-race-b")); if (races.Count(x => x != null) != 1) throw new Exception("Concurrent credits were double-spent."); var reservation = races.Single(x => x != null)!.Value; await w.DispatchAsync(admin, reservation, new(Guid.NewGuid(), "fixture.generator", "original-account", "demo-failed-run"), default); var failed = new CustomerSettlement(Guid.NewGuid(), "fixture.generator", "original-account", "demo-failed-run", "Failed", 0, "fixture:failed-generation"); await w.SettleAsync(admin, reservation, failed, default); await w.SettleAsync(admin, reservation, failed with { OperationId = Guid.NewGuid() }, default); if ((await w.WalletAsync(f.Alice, default)).Available != 100) throw new Exception("Failed generation did not release exactly once.");
var (credits, a) = await CustomerTestFixture.Catalog(w, f); var subscription = await w.ProductAsync(admin, new(Guid.NewGuid(), "geeta-plus", 1, "Subscription", "INR", 1000, 0, 30, ["GeetaPlus", "ReadPlus"], f.Universe), default); var creditOrder = await w.SubmitAsync(f.Alice, await w.CheckoutAsync(f.Alice, new(Guid.NewGuid(), credits, "Instagram"), default), default); var subOrder = await w.SubmitAsync(f.Alice, await w.CheckoutAsync(f.Alice, new(Guid.NewGuid(), subscription, "Unknown"), default), default);
var paid = CustomerTestFixture.Evidence(creditOrder); var subscriptionPaid = CustomerTestFixture.Evidence(subOrder); var refund = CustomerTestFixture.Evidence(creditOrder, 3, "Refunded", 1000, paid.OccurredUtc); var delayed = paid with { EventId = "delayed-original-paid", Sequence = 2 }; var cancel = CustomerTestFixture.Evidence(subOrder, 2, "Cancelled");
var b = await w.RouteAsync(admin, new(Guid.NewGuid(), "payments", 2, "payment.fixture.b.v1", "replacement-account"), default); await w.ControlRouteAsync(admin, b, new(Guid.NewGuid(), true, true), default); var newer = await w.SubmitAsync(f.Alice, await w.CheckoutAsync(f.Alice, new(Guid.NewGuid(), credits), default), default); if (newer.Provider != "payment.fixture.b.v1" || creditOrder.Provider != "payment.fixture.a.v1") throw new Exception("Original provider binding changed.");
foreach (var provider in new[] { "identity.fixture.a.v1", "identity.fixture.b.v1" }) { var challenge = await w.ChallengeAsync(f.Alice, new(Guid.NewGuid(), provider, "fixture-account"), default); await w.LinkAsync(f.Alice, CustomerTestFixture.Proof(f.Alice, challenge, "fixture-subject"), default); } if ((await w.MeAsync(f.Alice, default)).Id != f.User) throw new Exception("Identity switch replaced user.");
var other = CustomerTestFixture.Scope(f.Tenant, "fixture-other:" + f.User.ToString("N")); await w.RegisterAsync(other, new(Guid.NewGuid(), "Other fixture", true), default); var otherHouse = await w.HouseholdAsync(other, new(Guid.NewGuid(), "Isolated household"), default); var otherProfile = await w.ProfileAsync(other, new(Guid.NewGuid(), otherHouse, "Private fixture", "Adult", "en-IN"), default); var isolated = false; try { await w.ProgressAsync(f.Alice, otherProfile, default); } catch (CoreAccessException) { isolated = true; } if (!isolated) throw new Exception("Household isolation failed.");
var child = await w.ProfileAsync(f.Alice, new(Guid.NewGuid(), f.Household, "Fixture child", "Child", "en-IN"), default); await w.ConsentAsync(f.Alice, new(Guid.NewGuid(), child, "Progress", true, DateTimeOffset.UtcNow.AddDays(1), "fixture:parent-progress"), default); await w.ProgressAsync(f.Alice, child, new(Guid.NewGuid(), "", "geeta-reading", 4, true), default);
var jsonOptions = new JsonSerializerOptions { WriteIndented = true, PropertyNamingPolicy = JsonNamingPolicy.CamelCase };
void Save(string name, object data) => File.WriteAllText(Path.Combine(directory, name), JsonSerializer.Serialize(data, jsonOptions));
Save("fixture.json", new { f.Tenant, f.Universe, f.User, f.Household, f.Profile, child, otherProfile, creditOrder = creditOrder.Id, subscriptionOrder = subOrder.Id, newProviderOrder = newer.Id, concurrentReservationsSucceeded = 1, failedGenerationReleasedOnce = true, identityLinksPreserveUser = true, householdIsolationChecked = true });
Save("paid.json", FixturePaymentProvider.Sign(paid, CustomerTestFixture.Secret)); Save("subscription-paid.json", FixturePaymentProvider.Sign(subscriptionPaid, CustomerTestFixture.Secret)); Save("refund.json", FixturePaymentProvider.Sign(refund, CustomerTestFixture.Secret)); Save("delayed-paid.json", FixturePaymentProvider.Sign(delayed, CustomerTestFixture.Secret)); Save("cancel.json", FixturePaymentProvider.Sign(cancel, CustomerTestFixture.Secret));
Console.WriteLine("Controlled M20 fixture ready: one concurrent spend admitted; failed work released once; private signed test payment events prepared. No real charge or external account.");
